WITH RECURSIVE x8 AS (SELECT 1 UNION ALL SELECT 1 + x7.v52264 FROM x12 WHERE x7.v52264 < 2000) SELECT x7.v52264, x7.v52264, LEAST(CAST('2001-01-01 00:00:00' AS DATETIME(1)), CAST('2001-01-01 00:00:00' AS DATETIME(2))) AS x4, x7.v52264 FROM v52263 AS x7 WHERE x7.v52264 = 0 AND x7.v52264 = 0 AND x7.v52264 = TIME(STR_TO_DATE(DATE_FORMAT('2009-05-04', CONCAT_WS(':', '%i', '%a', '%x', '%s', '%j')), CONCAT_WS('-', '%V', '%s', '%U')))